// FILE PATH: app/page.tsx
'use client';

import React, { useState } from 'react';
import { motion, useReducedMotion } from 'framer-motion';
import BootSequence from '@/components/entry/BootSequence';
import Scene3D from '@/components/canvas/Scene3D';
import FloatingHUD from '@/components/navigation/FloatingHUD';
import RoboticAgent from '@/components/ui/RoboticAgent';
import BookingModal from '@/components/modals/BookingModal';
import { ArrowUpRight, Cpu, Layers, ShieldAlert, Sparkles, Terminal } from 'lucide-react';

const PORTFOLIO_PROJECTS = [
  {
    id: '01',
    code: 'PRJ // HYPERION-GL',
    title: 'AETHERIUS QUANTUM TELEMETRY',
    category: 'CUSTOM GLSL SHADERS / NEXT.JS / RUST WASM',
    metrics: '120 FPS LOCKED // 1.4M PARTICLES',
    description:
      'Real-time spatial command interface rendering live satellite orbital mechanics directly inside a zero-latency WebGL browser viewport.',
  },
  {
    id: '02',
    code: 'PRJ // KRYPTON-OS',
    title: 'OBSIDIAN FINTECH KERNEL',
    category: 'ZERO-KNOWLEDGE AUTH / SPATIAL UI',
    metrics: '0.02s EXECUTION // INSTITUTIONAL GRADE',
    description:
      'Algorithmic liquidity visualization engine engineered with bespoke geometric wireframes and hardware-accelerated micro-interactions.',
  },
  {
    id: '03',
    code: 'PRJ // NEURAL-SYNTH',
    title: 'VORTEX AI COMPUTE ENGINE',
    category: 'THREE.JS / DISTRIBUTED NODE GRAPH',
    metrics: '99.99% UPTIME // ENTERPRISE FLEX',
    description:
      'Interactive 3D neural topology mapper allowing engineers to inspect live tensor weights in real-time 3D space.',
  },
];

export default function HomePage() {
  const shouldReduceMotion = useReducedMotion();
  const [bootCompleted, setBootCompleted] = useState(false);
  const [bookingOpen, setBookingOpen] = useState(false);
  const [activeSandbox, setActiveSandbox] = useState<string | null>(null);

  return (
    <main className="relative min-h-screen bg-[#030303] text-white overflow-x-hidden">
      {/* 1. Cinematic 1-Sec Eyes -> Robotic Head Boot Sequence */}
      <BootSequence onComplete={() => setBootCompleted(true)} />

      {/* 2. Background 3D Transparent Wireframe Core + Shifting Crimson Gradients */}
      <Scene3D />

      {/* 3. Navbar-less Floating Architectural HUD Nodes */}
      <FloatingHUD
        ready={bootCompleted}
        onOpenBooking={() => setBookingOpen(true)}
      />

      {/* 4. Docked Robotic Q&A Assistant in Bottom-Right Corner */}
      <RoboticAgent ready={bootCompleted} />

      {/* 5. Call & Inquiry Terminal Modal */}
      <BookingModal
        isOpen={bookingOpen}
        onClose={() => setBookingOpen(false)}
      />

      {/* HERO SECTION: Smooth Physics Entrance After Boot */}
      <section className="relative z-10 flex min-h-screen flex-col justify-center px-6 sm:px-16 lg:px-28 pt-20">
        <div
          className={`max-w-5xl transition-all duration-1000 ease-out ${
            bootCompleted
              ? 'opacity-100 translate-y-0'
              : 'opacity-0 translate-y-12'
          }`}
        >
          <div className="inline-flex items-center space-x-3 border border-red-500/40 bg-red-950/20 px-3.5 py-1.5 backdrop-blur-md hud-clip">
            <span className="h-1.5 w-1.5 rounded-full bg-red-500 animate-ping" />
            <span className="font-mono text-[10px] tracking-[0.3em] text-red-400 uppercase">
              WE ARE TECHNOVA STUDIO // ELITE ENGINEERING COLLECTIVE
            </span>
          </div>

          <h1 className="mt-6 text-5xl sm:text-7xl lg:text-[5.5rem] font-extrabold tracking-tighter leading-[0.94] uppercase">
            WE BUILD <br />
            <span className="bg-gradient-to-r from-white via-red-200 to-red-600 bg-clip-text text-transparent">
              BEYOND DIGITAL
            </span>{' '}
            <br />
            EXPERIENCES.
          </h1>

          <p className="mt-6 max-w-xl text-sm sm:text-base text-zinc-400 font-light leading-relaxed">
            An organization of high-end systems architects and creative technologists crafting digital monuments that make engineers inspect the source code in disbelief.
          </p>

          {/* Unique HUD Wireframe Buttons */}
          <div className="mt-10 flex flex-wrap items-center gap-4">
            <button
              onClick={() =>
                document
                  .getElementById('work-matrix')
                  ?.scrollIntoView({ behavior: 'smooth' })
              }
              data-hud-interactive="true"
              className="group relative border border-red-500 bg-red-600/20 px-8 py-4 font-mono text-xs tracking-[0.25em] text-white uppercase hover:bg-red-600 transition-all hud-clip shadow-[0_0_35px_rgba(220,38,38,0.25)]"
            >
              <span>EXPLORE OUR WORK</span>
            </button>

            <button
              onClick={() => setBookingOpen(true)}
              data-hud-interactive="true"
              className="group relative border border-white/20 bg-white/[0.03] backdrop-blur-md px-8 py-4 font-mono text-xs tracking-[0.25em] text-zinc-200 uppercase hover:border-red-500/70 hover:text-white transition-all hud-clip"
            >
              <span>BOOK EXECUTIVE CALL</span>
            </button>
          </div>
        </div>

        {/* Service Pillars Bar (Inspired by Reference 1) */}
        <div
          className={`mt-20 grid grid-cols-1 sm:grid-cols-3 gap-6 border-t border-white/10 pt-8 max-w-4xl transition-all duration-1000 delay-300 ${
            bootCompleted
              ? 'opacity-100 translate-y-0'
              : 'opacity-0 translate-y-10'
          }`}
        >
          {[
            { num: '01', title: 'SPATIAL WEBGL & 3D ARCHITECTURES' },
            { num: '02', title: 'HIGH-FREQUENCY FULLSTACK KERNELS' },
            { num: '03', title: 'BESPOKE AI & TELEMETRY INTERFACES' },
          ].map((pillar) => (
            <div key={pillar.num} className="flex items-start space-x-3">
              <span className="font-mono text-xs text-red-500 font-bold">
                {pillar.num}
              </span>
              <span className="font-mono text-[11px] tracking-[0.18em] text-zinc-300">
                {pillar.title}
              </span>
            </div>
          ))}
        </div>
      </section>

      {/* WORK / PORTFOLIO ENGINE */}
      <section
        id="work-matrix"
        className="relative z-10 px-6 sm:px-16 lg:px-28 py-28 border-t border-white/10 bg-gradient-to-b from-transparent via-[#050505]/90 to-[#030303]"
      >
        <div className="flex flex-col md:flex-row md:items-end justify-between mb-16">
          <div>
            <p className="font-mono text-[10px] tracking-[0.35em] text-red-500 uppercase">
              SELECTED ARCHITECTURE // VERIFIED DEPLOYMENTS
            </p>
            <h2 className="mt-2 text-3xl sm:text-5xl font-bold tracking-tight uppercase">
              EXPLORE DREAMS
            </h2>
          </div>
          <p className="mt-4 md:mt-0 font-mono text-xs text-zinc-400 max-w-sm">
            Every deployment is custom-engineered from raw shaders and low-level state machines. Click any card to inspect live telemetry.
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {PORTFOLIO_PROJECTS.map((project, index) => {
            const isSelected = activeSandbox === project.id;
            return (
              <motion.div
                key={project.id}
                initial={
                  shouldReduceMotion
                    ? false
                    : { opacity: 0, y: 72, rotateX: 8, scale: 0.96 }
                }
                whileInView={{ opacity: 1, y: 0, rotateX: 0, scale: 1 }}
                viewport={{ once: true, amount: 0.2 }}
                transition={
                  shouldReduceMotion
                    ? { duration: 0 }
                    : {
                        type: 'spring',
                        stiffness: 85,
                        damping: 18,
                        delay: index * 0.14,
                      }
                }
                onClick={() =>
                  setActiveSandbox(isSelected ? null : project.id)
                }
                data-hud-interactive="true"
                className="group relative border border-white/15 bg-[#070707]/85 backdrop-blur-xl p-7 hover:border-red-500/80 transition-all duration-300 hud-clip flex flex-col justify-between"
                style={{ transformOrigin: 'center bottom' }}
              >
                {/* Hover Dynamic Red Gradient Glow */}
                <div className="absolute -inset-1 bg-gradient-to-r from-red-600/0 via-red-600/10 to-red-900/0 opacity-0 group-hover:opacity-100 blur-xl transition-opacity pointer-events-none" />

                <div>
                  <div className="flex items-center justify-between font-mono text-[10px] text-zinc-400">
                    <span className="text-red-500">{project.code}</span>
                    <span>{project.metrics}</span>
                  </div>

                  <h3 className="mt-5 text-2xl font-bold tracking-tight text-white group-hover:text-red-400 transition-colors">
                    {project.title}
                  </h3>

                  <p className="mt-2 font-mono text-[10px] tracking-widest text-zinc-400">
                    {project.category}
                  </p>

                  <p className="mt-4 text-xs text-zinc-300 leading-relaxed">
                    {project.description}
                  </p>

                  {/* Interactive Live Telemetry Sandbox Preview */}
                  {isSelected && (
                    <div className="mt-5 border border-red-500/40 bg-black/90 p-4 font-mono text-[10px] text-red-400 space-y-1.5">
                      <div className="flex justify-between text-white">
                        <span>LIVE KERNEL DIAGNOSTIC</span>
                        <span className="text-emerald-400">ONLINE</span>
                      </div>
                      <div className="w-full bg-zinc-900 h-1.5 overflow-hidden">
                        <div className="bg-red-500 h-full w-4/5 animate-pulse" />
                      </div>
                      <p className="text-zinc-400">
                        SHADER_PIPELINE: COMPILED (0.004ms)
                      </p>
                    </div>
                  )}
                </div>

                <div className="mt-8 pt-4 border-t border-white/10 flex items-center justify-between font-mono text-[10px] tracking-widest text-zinc-300 group-hover:text-white">
                  <span>
                    {isSelected ? 'CLOSE SANDBOX' : 'LAUNCH LIVE TELEMETRY'}
                  </span>
                  <ArrowUpRight className="w-4 h-4 text-red-500 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
                </div>
              </motion.div>
            );
          })}
        </div>
      </section>

      {/* R&D LAB & CONVERSION SECTION */}
      <section
        id="lab-matrix"
        className="relative z-10 px-6 sm:px-16 lg:px-28 py-28 border-t border-white/10"
      >
        <div className="border border-red-500/40 bg-gradient-to-br from-[#0a0303] via-[#050505] to-[#120404] p-8 sm:p-14 hud-clip">
          <div className="max-w-3xl">
            <span className="font-mono text-[10px] tracking-[0.35em] text-red-500 uppercase">
              READY TO DEPLOY THE UNIMAGINABLE?
            </span>
            <h2 className="mt-3 text-3xl sm:text-5xl font-extrabold tracking-tight uppercase">
              COMMISSION TECHNOVA STUDIO FOR YOUR NEXT FLAGSHIP.
            </h2>
            <p className="mt-4 text-sm text-zinc-400 leading-relaxed">
              Initiate a call request or transmit your technical brief directly into our engineering command board.
            </p>
            <div className="mt-8 flex flex-wrap gap-4">
              <button
                onClick={() => setBookingOpen(true)}
                data-hud-interactive="true"
                className="border border-red-500 bg-red-600 px-8 py-4 font-mono text-xs tracking-[0.25em] text-white uppercase hover:bg-red-500 transition-all hud-clip"
              >
                INITIATE PROJECT BRIEF / CALL
              </button>
            </div>
          </div>
        </div>
      </section>
    </main>
  );
}